INSERT INTO "core"."archetypes" ("id", "name", "description", "strengths", "work_styles", "team_dynamics", "growth_areas", "mapping_rules", "created_at") VALUES
	('382538ca-3cbe-4f23-8246-38310d2795a6', 'Builder', 'High reliability, structured approach, methodical execution. Builders turn plans into tangible outcomes with precision and consistency.', '{Reliability,Precision,"Methodical approach",Quality-focused,Perseverance}', 'Prefers structured environments with clear processes. Excels at following blueprints and maintaining standards. Works best with defined timelines and measurable outcomes.', 'Provides stability and consistency to teams. Often the steady hand that ensures quality. Works well with visionaries who need reliable execution.', '{"Flexibility in ambiguous situations","Embracing experimentation","Adapting to rapid change"}', '[{"level": "high", "domain": "C", "weight": 1.0}, {"level": "neutral", "domain": "O", "weight": 0.5}]', '2025-11-18 21:04:16.979382+00'),
	('05a6caee-ec37-4c03-8ce0-f9f69193b7d2', 'Maker', 'High creativity combined with conscientiousness. Makers experiment and iterate, creating new solutions through hands-on prototyping.', '{Creativity,Practicality,Experimentation,Adaptability,Resourcefulness}', 'Thrives in experimental environments. Enjoys hands-on work and iterative problem-solving. Comfortable with uncertainty and rapid prototyping.', 'Brings innovation and fresh perspectives. Often the one who finds creative solutions. Works well with builders who can refine their prototypes.', '{"Following established processes","Long-term planning","Managing multiple priorities"}', '[{"level": "high", "domain": "C", "weight": 0.8}, {"level": "high", "domain": "O", "weight": 0.8}, {"level": "low", "domain": "E", "weight": 0.6}]', '2025-11-18 21:04:16.979382+00'),
	('9f842b61-3b43-46ed-ae7a-d44b583ba920', 'Operator', 'High conscientiousness with elevated neuroticism. Operators excel in risk-aware roles, maintaining systems and preventing problems.', '{Vigilance,"Risk awareness","System maintenance",Reliability,"Attention to detail"}', 'Thrives in roles requiring careful monitoring and risk management. Prefers structured processes with clear safety protocols. Works best in stable environments.', 'Provides critical oversight and risk management. Often the safety net for teams. Works well with innovators who need grounding.', '{"Embracing change","Taking calculated risks","Reducing excessive worry"}', '[{"level": "high", "domain": "C", "weight": 1.0}, {"level": "high", "domain": "N", "weight": 0.7}, {"level": "low", "domain": "O", "weight": 0.5}]', '2025-11-18 21:04:16.979382+00'),
	('8de97538-90ad-4193-a9ea-42f336f9b3c5', 'Designer', 'High openness with balanced extraversion. Designers shape beauty, harmony, and usability, balancing aesthetics with function.', '{"Aesthetic sensitivity","Creative problem-solving","Attention to detail",Empathy,"Visual thinking"}', 'Prefers creative environments with freedom to explore. Enjoys collaborative design processes. Works best with clear user needs and creative constraints.', 'Brings aesthetic vision and user-centered thinking. Often bridges technical and creative teams. Works well with builders who can execute their designs.', '{"Technical implementation details","Following strict specifications","Working in highly structured environments"}', '[{"level": "high", "domain": "O", "weight": 1.0}, {"level": "neutral", "domain": "E", "weight": 0.5}]', '2025-11-18 21:04:16.979382+00'),
	('a868822a-3b2c-4a70-b187-ba5f7ac7b368', 'Connector', 'High extraversion and agreeableness. Connectors build networks, harmony, and collaboration through relationships and communication.', '{"Social intelligence",Empathy,Collaboration,Communication,"Team building"}', 'Thrives in people-focused roles. Enjoys facilitating communication and building relationships. Works best in collaborative, team-oriented environments.', 'Essential for team cohesion and communication. Often the glue that holds teams together. Works well with all archetypes by facilitating connections.', '{"Working independently for extended periods","Focusing on technical details","Managing conflict directly"}', '[{"level": "high", "domain": "E", "weight": 1.0}, {"level": "high", "domain": "A", "weight": 0.8}]', '2025-11-18 21:04:16.979382+00'),
	('9ded6584-56e1-422c-abc8-6b780871d203', 'Analyst', 'Low extraversion with high openness and conscientiousness. Analysts seek truth, structure, and systems understanding through observation and measurement.', '{"Critical thinking","Pattern recognition",Precision,"Systems thinking","Methodical analysis"}', 'Prefers independent work with time for deep analysis. Enjoys data-driven environments. Works best with clear objectives and access to information.', 'Provides analytical depth and objective insights. Often the fact-checker and systems thinker. Works well with connectors who can communicate their findings.', '{"Social collaboration","Presenting to groups","Working in ambiguous situations"}', '[{"level": "low", "domain": "E", "weight": 0.8}, {"level": "high", "domain": "O", "weight": 0.8}, {"level": "high", "domain": "C", "weight": 0.7}]', '2025-11-18 21:04:16.979382+00'),
	('fb2406bf-9d36-4f78-bfd6-b089fc71d79e', 'Navigator', 'High extraversion and openness with low neuroticism. Navigators provide direction and decision-making under uncertainty with strategic reasoning.', '{Decisiveness,"Strategic thinking","Risk tolerance",Adaptability,Leadership}', 'Thrives in dynamic, uncertain environments. Enjoys making decisions and leading through ambiguity. Works best with autonomy and clear objectives.', 'Provides direction and confidence in uncertain situations. Often the decision-maker and strategic guide. Works well with operators who provide risk awareness.', '{"Following detailed instructions","Working in highly structured environments","Avoiding risk entirely"}', '[{"level": "high", "domain": "E", "weight": 1.0}, {"level": "high", "domain": "O", "weight": 0.8}, {"level": "low", "domain": "N", "weight": 0.6}]', '2025-11-18 21:04:16.979382+00'),
	('a6c377f1-2f84-4aec-93d8-a808bda0721c', 'Innovator', 'High openness and extraversion with low conscientiousness. Innovators imagine what doesn''t yet exist, creating bold new ideas and solutions.', '{Creativity,Boldness,"Future-oriented thinking",Ideation,Vision}', 'Thrives in creative, fast-moving environments. Enjoys ideation and exploring new possibilities. Works best with freedom and minimal constraints.', 'Brings bold ideas and future vision. Often the catalyst for change. Works well with builders who can execute their visions.', '{"Following established processes","Attention to detail","Long-term maintenance"}', '[{"level": "high", "domain": "O", "weight": 1.0}, {"level": "high", "domain": "E", "weight": 0.8}, {"level": "low", "domain": "C", "weight": 0.5}]', '2025-11-18 21:04:16.979382+00');
